INSERT INTO SUBPARTIDA (id_subpartida, codigo_10digitos, descripcion, es_terminal, fk_partida, fk_unidad, fk_subpartida_padre) VALUES (11991, '2009.90.00.00', '- Mezclas de jugos 14 5,12 ℓ CAPÍTULO 21 PREPARACIONES ALIMENTICIAS DIVERSAS Notas. 1. Este Capítulo no comprende: a) las mezclas de hortalizas de la partida 07.12; b) los sucedáneos del café tostados que contengan café en cualquier proporción (partida 09.01); c) el té aromatizado (partida 09.02); d) las especias y demás productos de las partidas 09.04 a 09.10; e) las preparaciones alimenticias que contengan una proporción superior al 20 % en peso de embutidos, carne, despojos, sangre, insectos, pescado o de crustáceos, moluscos o demás invertebrados acuáticos, o de una combinación de estos productos (Capítulo 16), excepto los productos descritos en las partidas 21.03 o 21.04; f) los productos de la partida 24.04; g) las levaduras acondicionadas como medicamentos y demás productos de las partidas 30.03 o 30.04; h) las preparaciones enzimáticas de la partida 35.07. 2. Los extractos de los sucedáneos mencionados en la Nota 1 b) anterior se clasifican en la partida 21.01. 3. En la partida 21.04, se entiende por preparaciones alimenticias compuestas homogeneizadas, las preparaciones que consistan en una mezcla finamente homogeneizada de varias sustancias básicas, tales como carne, pescado, hortalizas, frutas u otros frutos, acondicionadas para la venta al por menor como alimento para lactantes o niños de corta edad o para uso dietético en recipientes con un contenido de peso neto inferior o igual a 250 g. Para la aplicación de esta definición se hará abstracción, en su caso, de los diversos ingredientes añadidos a la mezcla en pequeña cantidad para sazonar, conservar u otros fines. Estas preparaciones pueden contener pequeñas cantidades de fragmentos visibles. Código Descripción de las Mercancías Tarifa Ad Valorem Régimen Legal Unidad AEC Ex.AEC Importación Exportación Física (1) (2) (3) (4) (5) (6) (7)', 0, 171, NULL, NULL);
