INSERT INTO SUBPARTIDA (id_subpartida, codigo_10digitos, descripcion, es_terminal, fk_partida, fk_unidad, fk_subpartida_padre) VALUES (12509, '4017.00.00.00', 'CAUCHO ENDURECIDO (POR EJEMPLO, EBONITA) EN CUALQUIER FORMA, INCLUIDOS LOS DESECHOS Y DESPERDICIOS; MANUFACTURAS DE CAUCHO ENDURECIDO. 16 0A kg SECCIÓN VIII PIELES, CUEROS, PELETERÍA Y MANUFACTURAS DE ESTAS MATERIAS; ARTÍCULOS DE TALABARTERÍA O GUARNICIONERÍA; ARTÍCULOS DE VIAJE, BOLSOS DE MANO (CARTERAS) Y CONTINENTES SIMILARES; MANUFACTURAS DE TRIPA CAPÍTULO 41 PIELES (EXCEPTO LA PELETERÍA) Y CUEROS Notas. 1. Este Capítulo no comprende: a) los recortes y desperdicios similares de cueros y pieles en bruto (partida 05.11); b) las pieles y partes de pieles de ave, con sus plumas o plumón (partidas 05.05 o 67.01, según los casos); c) los cueros y pieles en bruto, curtidos o adobados, sin depilar, de animales de pelo (Capítulo 43). Sin embargo, se clasifican en este Capítulo las pieles en bruto sin depilar de bovino (incluidas las de búfalo), de equino, ovino (excepto las de cordero llamadas astracán, «Breitschwanz», «caracul», «persa» o similares y las pieles de cordero de Indias, de China, de Mongolia o del Tíbet), de caprino (excepto las de cabra, cabritilla o cabrito del Yemen, de Mongolia o del Tíbet), de porcino (incluidas las de pecarí), de gamuza, gacela, camello, dromedario, reno, alce, ciervo, corzo o perro. 2. A) Las partidas 41.04 a 41.06 no comprenden los cueros y pieles que hayan sufrido un proceso de curtido (incluido el precurtido) reversible (partidas', 0, 488, NULL, NULL);
