INSERT INTO SUBPARTIDA (id_subpartida, codigo_10digitos, descripcion, es_terminal, fk_partida, fk_unidad, fk_subpartida_padre) VALUES (12566, '4115.20.00.00', '- Recortes y demás desperdicios de cuero o piel, preparados, o de cuero regenerado, no utilizables para la fabricación de manufacturas de cuero; aserrín, polvo y harina de cuero 10 kg CAPÍTULO 42 MANUFACTURAS DE CUERO; ARTÍCULOS DE TALABARTERÍA O GUARNICIONERÍA; ARTÍCULOS DE VIAJE, BOLSOS DE MANO (CARTERAS) Y CONTINENTES SIMILARES; MANUFACTURAS DE TRIPA Notas. 1. En este Capítulo, la expresión cuero natural comprende también los cueros y pieles agamuzados (incluido el agamuzado combinado al aceite), los cueros y pieles charolados y sus imitaciones de cueros o pieles chapados y los cueros y pieles metalizados. 2. Este Capítulo no comprende: a) los catguts estériles y las ligaduras estériles similares para suturas quirúrgicas (partida 30.06); b) las prendas y complementos (accesorios), de vestir (excepto los guantes, mitones y manoplas), de cuero o piel, forrados interiormente con peletería natural o peletería facticia o artificial, así como las prendas y complementos (accesorios), de vestir, de cuero o piel con partes exteriores de peletería natural o peletería facticia o artificial, cuando éstas superen el papel de simples guarniciones (partidas 43.03 o 43.04, según los casos); c) los artículos confeccionados con redes de la partida 56.08; d) los artículos del Capítulo 64; e) los sombreros, demás tocados, y sus partes, del Capítulo 65; f) los látigos, fustas y demás artículos de la partida 66.02; g) los gemelos, pulseras y demás artículos de bisutería (partida 71.17); h) los accesorios y guarniciones de talabartería o guarnicionería (por ejemplo: frenos, estribos, hebillas), presentados aisladamente (Sección XV, generalmente); ij) las cuerdas armónicas, parches de tambor o de instrumentos similares y demás partes de instrumentos musicales (partida 92.09); k) los artículos del Capítulo 94 (por ejemplo: muebles, luminarias y aparatos de alumbrado); l) los artículos del Capítulo 95 (por ejemplo: juguetes, juegos, artefactos deportivos); m) los botones, botones de presión, formas para botones y demás partes de botones o de botones de presión y esbozos de botones, de la partida 96.06. 3. A) Además de lo dispuesto en la Nota 2 anterior, la partida 42.02 no comprende: a) las bolsas de hojas de plástico, con asas, no concebidas para un uso prolongado, incluso impresas (partida 39.23); b) los artículos de materia trenzable (partida 46.02). B) Las manufacturas comprendidas en las partidas 42.02 y 42.03 con partes de metal precioso o de chapados de metal precioso (plaqué), de perlas finas (naturales)* o cultivadas o de piedras preciosas o semipreciosas (naturales, sintéticas o reconstituidas) permanecen incluidas en estas partidas, incluso si dichas partes exceden la función de simples accesorios o adornos de mínima importancia, a condición de que tales partes no confieran a las manufacturas su carácter esencial. Si, por el contrario, esas partes confieren a las manufacturas su carácter esencial, éstas deben clasificarse en el Capítulo 71. 4. En la partida 42.03, la expresión prendas y complementos (accesorios), de vestir se refiere, entre otros, a los guantes, mitones y manoplas (incluidos los de deporte y los de protección), a los delantales y demás equipos especiales de protección individual para cualquier oficio, a los tirantes (tiradores), cinturones, bandoleras, brazaletes y muñequeras, excepto las pulseras para relojes (partida 91.13). Código Descripción de las Mercancías Tarifa Ad Valorem Régimen Legal Unidad AEC Ex.AEC Importación Exportación Física (1) (2) (3) (4) (5) (6) (7)', 0, 499, NULL, NULL);
