INSERT INTO SUBPARTIDA (id_subpartida, codigo_10digitos, descripcion, es_terminal, fk_partida, fk_unidad, fk_subpartida_padre) VALUES (12924, '5311.00.00.00', 'TEJIDOS DE LAS DEMÁS FIBRAS TEXTILES VEGETALES; TEJIDOS DE HILADOS DE PAPEL. 26 m² CAPÍTULO 54 FILAMENTOS SINTÉTICOS O ARTIFICIALES; TIRAS Y FORMAS SIMILARES DE MATERIA TEXTIL SINTÉTICA O ARTIFICIAL Notas. 1. En la Nomenclatura, las expresiones fibras sintéticas y fibras artificiales se refieren a las fibras discontinuas y a los filamentos de polímeros orgánicos obtenidos industrialmente: a) por polimerización de monómeros orgánicos para obtener polímeros tales como poliamidas, poliésteres, poliolefinas o poliuretanos, o por modificación química de polímeros obtenidos por este procedimiento (por ejemplo, poli(alcohol vinílico) obtenido por hidrólisis del poli(acetato de vinilo)); b) por disolución o tratamiento químico de polímeros orgánicos naturales (por ejemplo, celulosa) para obtener polímeros tales como rayón cuproamónico (cupro) o rayón viscosa, o por modificación química de polímeros orgánicos naturales (por ejemplo: celulosa, caseína y otras proteínas, o ácido algínico) para obtener polímeros tales como acetato de celulosa o alginatos. Se consideran sintéticas las fibras definidas en a) y artificiales las definidas en b). Las tiras y formas similares de la partida 54.04 o 54.05 no se consideran fibras sintéticas o artificiales. Los términos sintético y artificial se aplican también, con el mismo sentido, a la expresión materia textil. 2. Las partidas 54.02 y 54.03 no comprenden los cables de filamentos sintéticos o artificiales del Capítulo 55. Código Descripción de las Mercancías Tarifa Ad Valorem Régimen Legal Unidad AEC Ex.AEC Importación Exportación Física (1) (2) (3) (4) (5) (6) (7)', 0, 617, NULL, NULL);
