INSERT INTO SUBPARTIDA (id_subpartida, codigo_10digitos, descripcion, es_terminal, fk_partida, fk_unidad, fk_subpartida_padre) VALUES (12962, '5408.34.00.00', '- - Estampados 26 m² 6.804 Extraordinario GACETA OFICIAL DE LA REPÚBLICA BOLIVARIANA DE VENEZUELA 205 CAPÍTULO 55 FIBRAS SINTÉTICAS O ARTIFICIALES DISCONTINUAS Nota. 1. En las partidas 55.01 y 55.02, se entiende por cables de filamentos sintéticos y cables de filamentos artificiales, los cables constituidos por un conjunto de filamentos paralelos de longitud uniforme e igual a la de los cables, que satisfagan las condiciones siguientes: a) longitud del cable superior a 2 m; b) torsión del cable inferior a 5 vueltas por metro; c) título unitario de los filamentos inferior a 67 decitex; d) solamente para los cables de filamentos sintéticos: que hayan sido estirados y, por ello, no puedan alargarse una proporción superior al 100 % de su longitud; e) título total del cable superior a 20.000 decitex. Los cables de longitud inferior o igual a 2 m se clasifican en las partidas 55.03 o 55.04. Código Descripción de las Mercancías Tarifa Ad Valorem Régimen Legal Unidad AEC Ex.AEC Importación Exportación Física (1) (2) (3) (4) (5) (6) (7)', 0, 625, NULL, NULL);
