INSERT INTO SUBPARTIDA (id_subpartida, codigo_10digitos, descripcion, es_terminal, fk_partida, fk_unidad, fk_subpartida_padre) VALUES (13034, '5516.93.00.00', '- - Con hilados de distintos colores 26 m²', 0, 641, NULL, NULL);
INSERT INTO SUBPARTIDA (id_subpartida, codigo_10digitos, descripcion, es_terminal, fk_partida, fk_unidad, fk_subpartida_padre) VALUES (13035, '5516.94.00.00', '- - Estampados 26 m² CAPÍTULO 56 GUATA, FIELTRO Y TELA SIN TEJER; HILADOS ESPECIALES; CORDELES, CUERDAS Y CORDAJES; ARTÍCULOS DE CORDELERÍA Notas. 1. Este Capítulo no comprende: a) la guata, fieltro y tela sin tejer, impregnados, recubiertos o revestidos de sustancias o preparaciones (por ejemplo: de perfume o cosméticos del Capítulo 33, de jabón o detergentes de la partida 34.01, de betunes o cremas para el calzado, encáusticos, abrillantadores (lustres), etc. o preparaciones similares de la partida 34.05, de suavizantes para textiles de la partida 38.09), cuando la materia textil sea un simple soporte; b) los productos textiles de la partida 58.11; c) los abrasivos naturales o artificiales, en polvo o gránulos, con soporte de fieltro o tela sin tejer (partida 68.05); d) la mica aglomerada o reconstituida con soporte de fieltro o tela sin tejer (partida 68.14); e) las hojas y tiras delgadas de metal con soporte de fieltro o tela sin tejer (generalmente Secciones XIV o XV); f) las compresas y los tampones higiénicos, pañales y artículos similares de la partida 96.19. 2. El término fieltro comprende también el fieltro punzonado y los productos constituidos por una capa de fibra textil cuya cohesión se ha reforzado mediante costura por cadeneta con las fibras de la propia capa. 3. Las partidas 56.02 y 56.03 comprenden respectivamente el fieltro y la tela sin tejer, impregnados, recubiertos, revestidos o estratificados con plástico o caucho, cualquiera que sea la naturaleza de estas materias (compacta o celular). La partida 56.03 comprende, además, la tela sin tejer aglomerada con plástico o caucho. Las partidas 56.02 y 56.03 no comprenden, sin embargo: a) el fieltro impregnado, recubierto, revestido o estratificado, con plástico o caucho, con un contenido de materia textil inferior o igual al 50 % en peso, así como el fieltro inmerso totalmente en plástico o caucho (Capítulos 39 o 40); b) la tela sin tejer totalmente inmersa en plástico o caucho o totalmente recubierta o revestida por las dos caras con estas mismas materias, siempre que el recubrimiento o revestimiento sea perceptible a simple vista, hecha abstracción para la aplicación de esta disposición de los cambios de color producidos por estas operaciones (Capítulos 39 o 40); c) las placas, hojas o tiras, de plástico o caucho celulares, combinadas con fieltro o tela sin tejer, en las que la materia textil sea un simple soporte (Capítulos 39 o 40). 4. La partida 56.04 no comprende los hilados textiles, ni las tiras y formas similares de las partidas 54.04 o 54.05, cuya impregnación, recubrimiento o revestimiento no sea perceptible a simple vista (Capítulos 50 a 55, generalmente); para la aplicación de esta disposición, se hará abstracción de los cambios de color producidos por estas operaciones. Código Descripción de las Mercancías Tarifa Ad Valorem Régimen Legal Unidad AEC Ex.AEC Importación Exportación Física (1) (2) (3) (4) (5) (6) (7)', 0, 641, NULL, NULL);
