INSERT INTO SUBPARTIDA (id_subpartida, codigo_10digitos, descripcion, es_terminal, fk_partida, fk_unidad, fk_subpartida_padre) VALUES (13108, '5705.00.00.00', 'LAS DEMÁS ALFOMBRAS Y REVESTIMIENTOS PARA EL SUELO, DE 35 0A m² MATERIA TEXTIL, INCLUSO CONFECCIONADOS. CAPÍTULO 58 TEJIDOS ESPECIALES; SUPERFICIES TEXTILES CON MECHÓN INSERTADO; ENCAJES; TAPICERÍA; PASAMANERÍA; BORDADOS Notas. 1. No se clasifican en este Capítulo los tejidos especificados en la Nota 1 del Capítulo 59, impregnados, recubiertos, revestidos o estratificados ni los demás productos del Capítulo 59. 2. Se clasifican también en la partida 58.01 el terciopelo y la felpa por trama sin cortar todavía que no presenten ni pelo ni bucles en la superficie. 3. En la partida 58.03, se entiende por tejido de gasa de vuelta el tejido en el que la urdimbre esté compuesta en toda o parte de su superficie por hilos fijos (hilos derechos) y por hilos móviles (hilos de vuelta) que se cruzan con los fijos dando media vuelta, una vuelta completa o más de una vuelta, para formar un bucle que aprisiona la trama. 4. No se clasifican en la partida 58.04 las redes de mallas anudadas, en paño o en pieza, fabricadas con cordeles, cuerdas o cordajes, de la partida 56.08. 5. En la partida 58.06, se entiende por cintas: a) - los tejidos (incluido el terciopelo) en tiras de anchura inferior o igual a 30 cm y con orillos verdaderos; - las tiras de anchura inferior o igual a 30 cm obtenidas por corte de tejido y provistas de falsos orillos tejidos, pegados u obtenidos de otra forma; b) los tejidos tubulares que, aplanados, tengan una anchura inferior o igual a 30 cm; c) los tejidos al bies con bordes plegados de anchura inferior o igual a 30 cm una vez desplegados. Las cintas con flecos obtenidos durante el tejido se clasifican en la partida 58.08. 6. El término bordados de la partida 58.10 se extiende a las aplicaciones por costura de lentejuelas, cuentas o motivos decorativos de textil u otra materia, así como a los trabajos realizados con hilos bordadores de metal o fibra de vidrio. Se excluye de la partida 58.10 la tapicería de aguja (partida 58.05). 7. Además de los productos de la partida 58.09, se clasifican también en las partidas de este Capítulo los productos hechos con hilos de metal, de los tipos utilizados en prendas de vestir, tapicería o usos similares. Código Descripción de las Mercancías Tarifa Ad Valorem Régimen Legal Unidad AEC Ex.AEC Importación Exportación Física (1) (2) (3) (4) (5) (6) (7)', 0, 655, NULL, NULL);
