INSERT INTO SUBPARTIDA (id_subpartida, codigo_10digitos, descripcion, es_terminal, fk_partida, fk_unidad, fk_subpartida_padre) VALUES (13686, '8609.00.00.00', 'CONTENEDORES (INCLUIDOS LOS CONTENEDORES CISTERNA Y LOS CONTENEDORES DEPÓSITO) ESPECIALMENTE DISEÑADOS Y 14BK u EQUIPADOS PARA UNO O VARIOS MEDIOS DE TRANSPORTE. CAPÍTULO 87 VEHÍCULOS AUTOMÓVILES, TRACTORES, VELOCÍPEDOS Y DEMÁS VEHÍCULOS TERRESTRES; SUS PARTES Y ACCESORIOS Notas. 1. Este Capítulo no comprende los vehículos diseñados para circular solamente sobre carriles (rieles). 2. En este Capítulo, se entiende por tractores los vehículos con motor esencialmente diseñados para tirar o empujar otros aparatos, vehículos o cargas, incluso si tienen ciertos acondicionamientos accesorios en relación con su utilización principal, que permitan el transporte de herramientas, semillas, abonos, etc. Las máquinas e instrumentos de trabajo diseñados para equipar los tractores de la partida 87.01 como material intercambiable siguen su propio régimen, aunque se presenten con el tractor, incluso si están montados sobre éste. 3. Los chasis con cabina incorporada para vehículos automóviles se clasifican en las partidas 87.02 a 87.04 y no en la partida 87.06. 4. La partida 87.12 comprende todas las bicicletas para niños. Los demás velocípedos para niños se clasifican en la partida 95.03. Nota de subpartida. 1. La subpartida 8708.22 comprende: a) los parabrisas, vidrios traseros (lunetas)* y demás ventanillas, enmarcados; b) los parabrisas, vidrios traseros (lunetas)* y demás ventanillas, incluso enmarcados, que incorporen dispositivos de calefacción u otros dispositivos eléctricos o electrónicos, siempre que estén destinados exclusiva o principalmente a vehículos automóviles de las partidas 87.01 a 87.05. Notas Complementarias. 1. A los efectos de la importación de vehículos, chasis con motor y carrocería, clasificados en las partidas 87.01, 87.02, 87.03 (excepto: 8703.10.00.00),', 0, 1101, NULL, NULL);
