INSERT INTO SUBPARTIDA (id_subpartida, codigo_10digitos, descripcion, es_terminal, fk_partida, fk_unidad, fk_subpartida_padre) VALUES (13957, '9872.00.00.00', '- MERCANCÍAS IMPORTADAS POR LOS DEMÁS ÓRGANOS O ENTES DE LA ADMINISTRACIÓN PÚBLICA 0 u 6.804 Extraordinario GACETA OFICIAL DE LA REPÚBLICA BOLIVARIANA DE VENEZUELA 371 REPÚBLICA BOLIVARIANA DE VENEZUELA DESPACHO DEL PRESIDENTE CAPÍTULO V DISPOSICIONES TRANSITORIAS Y FINALES DISPOSICIÓN TRANSITORIA Articulo 38. Sin menoscabo de los requisitos indicados en las columnas cinco (5) y seis (6) del artículo 37 de este Decreto, se suspende por un lapso de treinta (30) días continuos, contados a partir de la fecha de su publicación en la Gaceta Oficial de la República Bolivariana de Venezuela, la exigibilidad de los Regímenes Legales designados a mercancías que no se encontraban afectadas por los mismos en el Decreto que se deroga conforme se señala en el artículo 41. A tal efecto, se deberán aplicar las respectivas tablas de correlación entre la nomenclatura contenida en el Decreto que se deroga y la nomenclatura establecida en este Decreto, las cuales serán divulgadas por la Administración Aduanera. Los Permisos, Licencias, Registros, Certificados de Calidad o cualquier otro requisito, establecido en este Decreto, que hayan sido emitidos por los organismos oficiales correspondientes, en fecha anterior a la entrada en vigor del mismo y que aún se encuentren vigentes, serán aceptados por las autoridades aduaneras a los efectos de la declaración de aduanas. Se exceptúan de la disposición anterior aquellas mercancías que se encuentren de prohibida importación (Régimen Legal 1), de acuerdo a este Decreto. DISPOSICIONES FINALES Articulo 39. Sin menoscabo de lo dispuesto en este Decreto, el Ministro o Ministra del Poder Popular con competencia en materia de REPÚB D L E IC S A Pe A BcC OoH L OnIV oD AR EmI L A P NíaR A E ,D S E IfD iVnE E NaN T EnE Z zUaELsA y comercio exterior podrá, mediante Resolución, modificar o reformar este Arancel de Aduanas con el propósito de instrumentar las políticas arancelarias y paraarancelarias que regirán el comercio exterior. Articulo 40. Este Decreto entrará en vigencia cumplido el plazo de treinta (30) días continuos a partir del día siguiente de su publicación en la Gaceta Oficial de la República Bolivariana de Venezuela. Articulo 41. Se deroga el Decreto 2.647 de fecha 30/12/2016, publicado en Gaceta Oficial N° 6.281 Extraordinario, de fecha 30/12/2016, modificado parcialmente a través de los Decretos Nos. 4.111, 4.684, 4.728, 4.734, 4.758, 4.822 y 4.908 de fechas 05/02/2020, 02/05/2022, 23/08/2022, 02/09/2022, 29/12/2022, 01/07/2023 y 29/12/2023, publicados en las Gacetas Oficiales Nos. 6.510 Extraordinario, 6.698 Extraordinario, 42.446, 42.454, 6.727, 6.750 Extraordinario y 6.784 Extraordinario de las mismas fechas respectivamente. En cuanto a los Oficios de Clasificación Arancelaria, Clasificación Arancelaria Única (CAU) y Material de Ensamblaje Importado para Vehículos (MEIV), emanados con base en el Decreto mencionado en el párrafo anterior, la Gerencia de Arancel de la Intendencia Nacional de Aduanas del Servicio Nacional Integrado de Administración Aduanera y Tributaria (SENIAT), divulgará la correspondiente correlación entre la nomenclatura contenida en el Decreto derogado y la nomenclatura establecida en este Decreto, a los fines de armonizar el régimen general aplicable. En lo que respecta a las Autorizaciones para importar bajo Clasificación Arancelaria Única (CAU), en un solo embarque o en embarques fraccionados y Autorizaciones para importar bajo el Régimen de Material de Ensamblaje Importado para Vehículos (MEIV), que aún se encuentren vigentes, el gravamen ad valorem y el Régimen Legal aplicable a las mercancías descritas en dichos oficios, serán los contenidos en este Decreto, a tenor de lo dispuesto en el artículo 117 del Decreto Constituyente mediante el cual se REPÚBLICA BOLIVARIANA DE VENEZUELA DESPACHO DEL PRESIDENTE instrumentar las políticas arancelarias y paraarancelarias que regirán el comercio exterior. Articulo 40. Este Decreto entrará en vigencia cumplido el plazo de treinta (30) días continuos a partir del día siguiente de su publicación en la Gaceta Oficial de la República Bolivariana de Venezuela. Articulo 41. Se deroga el Decreto 2.647 de fecha 30/12/2016, publicado en Gaceta Oficial N° 6.281 Extraordinario, de fecha 30/12/2016, modificado parcialmente a través de los Decretos Nos. 4.111, 4.684, 4.728, 4.734, 4.758, 4.822 y 4.908 de fechas 05/02/2020, 02/05/2022, 23/08/2022, 02/09/2022, 29/12/2022, 01/07/2023 y 29/12/2023, publicados en las Gacetas Oficiales Nos. 6.510 Extraordinario, 6.698 Extraordinario, 42.446, 42.454, 6.727, 6.750 Extraordinario y 6.784 Extraordinario de las mismas fechas respectivamente. 372 GACEETnA c OuaFnItCoI AaL loDsE OLfAic iRoEs PdÚeB CLlIaCsiAfi cBaOcióLnI VAArRanIAceNlaAri aD,E C VlaEsNifiEcaZcUióEnL A 6.804 Extraordinario Arancelaria Única (CAU) y Material de Ensamblaje Importado para Vehículos (MEIV), emanados con base en el Decreto mencionado en el párrafo anterior, la Gerencia de Arancel de la Intendencia Nacional de Aduanas del Servicio Nacional Integrado de Administración Aduanera y Tributaria (SENIAT), divulgará la correspondiente correlación entre la nomenclatura contenida en el Decreto derogado y la nomenclatura establecida en este Decreto, a los fines de armonizar el régimen general aplicable. En lo que respecta a las Autorizaciones para importar bajo Clasificación Arancelaria Única (CAU), en un solo embarque o en embarques fraccionados y Autorizaciones para importar bajo el Régimen de Material de Ensamblaje Importado para Vehículos (MEIV), que aún se encuentren vigentes, el gravamen ad valorem y el Régimen Legal aplicable a las mercancías descritas en dichos REPÚBLICAo BfOicLIiVoAsR,IA sNAe DráE nVE NloEZsU EcLoAn tenidos en este Decreto, a tenor de lo dispuesto DESPACHO DEL PRESIDENTE e n el artículo 117 del Decreto Constituyente med